<?php require __DIR__.'/../../includes/admin_auth.php';$pdo=db();$lists=['authors'=>$pdo->query("SELECT id,CONCAT(first_name,' ',last_name) name FROM authors ORDER BY last_name")->fetchAll(),'publishers'=>$pdo->query('SELECT id,name FROM publishers ORDER BY name')->fetchAll(),'categories'=>$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll()];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$s=$pdo->prepare('INSERT INTO books(title,isbn,description,publication_year,pages,language,author_id,publisher_id,category_id) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([trim($_POST['title']),trim($_POST['isbn']),trim($_POST['description']),(int)$_POST['publication_year'],(int)$_POST['pages'],trim($_POST['language']),(int)$_POST['author_id'],(int)$_POST['publisher_id'],(int)$_POST['category_id']]);log_action(user()['id'],'ADD_BOOK','book',(int)$pdo->lastInsertId(),'Added book');flash('success','Book created. Add physical copies next.');header('Location: copies.php?book_id='.$pdo->lastInsertId());exit;}catch(Throwable $e){flash('error','Unable to create book. Ensure ISBN is unique and all selections are valid.');}}$pageTitle='Add book';require __DIR__.'/../../includes/header.php';?><div class="panel"><h1>Add book</h1><?php require __DIR__.'/_form.php';?></div><?php require __DIR__.'/../../includes/footer.php'; ?>
